import {z} from 'zod';
import {Id} from '../core/identifiers.js';
import type {NativeHeadFace} from './native-head-face.js';

const Scalar=z.number().finite().nonnegative();
const Rect=z.object({x:Scalar,y:Scalar,width:z.number().finite().positive(),height:z.number().finite().positive()}).strict();
const Source=z.object({sha256:z.string().regex(/^[a-f0-9]{64}$/),width:z.number().int().positive().max(8192),height:z.number().int().positive().max(8192)}).strict();
/** Authored source-space partitions, not inferred anatomy or the neck seam.
 * region paints behind the BODY; frontCut removes only its interior from the
 * original foreground image. The explicit narrow overlap avoids a clipping
 * crack, but its actual alpha/colour seam still needs visual acceptance. */
export const NativeHeadPaintSchema=z.object({version:z.literal('native-head-paint-1'),source:Source,
  rear:z.array(z.object({id:Id,region:Rect,frontCut:Rect}).strict()).max(8),
  status:z.literal('engineering-paint-registration'),approved:z.literal(false),productionReady:z.literal(false),motionVerified:z.literal(false),
}).strict();
export type NativeHeadPaint=z.infer<typeof NativeHeadPaintSchema>;
type R=z.infer<typeof Rect>;type P={x:number;y:number};
const within=(a:R,b:R)=>a.x>=b.x&&a.y>=b.y&&a.x+a.width<=b.x+b.width&&a.y+a.height<=b.y+b.height;
const box=(ps:P[]):R=>({x:Math.min(...ps.map(p=>p.x)),y:Math.min(...ps.map(p=>p.y)),width:Math.max(...ps.map(p=>p.x))-Math.min(...ps.map(p=>p.x)),height:Math.max(...ps.map(p=>p.y))-Math.min(...ps.map(p=>p.y))});
const touches=(a:R,b:R)=>a.x<=b.x+b.width&&b.x<=a.x+a.width&&a.y<=b.y+b.height&&b.y<=a.y+a.height;
export function validateNativeHeadPaint(value:NativeHeadPaint,source:z.infer<typeof Source>,cell:{crop:R;neck:P;neckTop:P;chin:P;eyeTarget:P;seam:P[];face?:NativeHeadFace}){
  const paint=NativeHeadPaintSchema.parse(value),fail=(message:string):never=>{throw new Error('needs-head-paint-registration: '+message);};
  if(paint.source.sha256!==source.sha256||paint.source.width!==source.width||paint.source.height!==source.height)fail('paint must belong to this exact cell PNG');
  const full={x:0,y:0,width:source.width,height:source.height};
  if(!within(cell.crop,full)||source.width*source.height>20_000_000)fail('crop leaves bounded source');
  if(new Set(paint.rear.map(p=>p.id)).size!==paint.rear.length)fail('duplicate rear layer');
  const f=cell.face,protect=[box(cell.seam),...[cell.neck,cell.neckTop,cell.chin,cell.eyeTarget].map(p=>({x:p.x,y:p.y,width:0,height:0})),
    ...(f?[f.mouth.region,...Object.values(f.eyes).map(e=>e.region),...f.protectedContours,...(f.emotions?Object.values(f.emotions.brows).map(b=>b.region):[])].map(box):[]),
    ...(f?Object.values(f.eyes).map(e=>e.strip):[]),...(f?.mouth.strip?[f.mouth.strip]:[]),
    ...(f?.emotions?Object.values(f.emotions.brows).map(b=>b.strip):[]),
    ...(f?.emotions?.mouth.repair.source.sha256===source.sha256?[f.emotions.mouth.repair.strip]:[])];
  for(const [i,p] of paint.rear.entries()){
    if(!within(p.region,cell.crop)||!within(p.frontCut,p.region))fail('rear paint or front cut leaves its cell/partition');
    // Overlap is explicitly authored and bounded at each internal edge. Crop
    // edges may coincide: they have no second paint seam outside the image.
    const inset=[p.frontCut.x-p.region.x,p.frontCut.y-p.region.y,p.region.x+p.region.width-p.frontCut.x-p.frontCut.width,p.region.y+p.region.height-p.frontCut.y-p.frontCut.height];
    if(inset.some(n=>n<0||n>2)||inset.every(n=>n===0))fail('partition needs an explicit overlap of at most two source pixels');
    if(protect.some(r=>touches(p.region,r)))fail('rear layer touches facial edits, landmarks or neck overlap; author a separate source partition');
    if(paint.rear.slice(i+1).some(q=>touches(p.region,q.region)))fail('rear layers overlap');
  }
}
const rect=(r:R,colour?:string)=>`<rect x="${r.x}" y="${r.y}" width="${r.width}" height="${r.height}"${colour?` fill="${colour}"`:''}/>`;
export function nativeHeadPaintDefs(paint:NativeHeadPaint,crop:R,index:number){
  if(!paint.rear.length)return '';
  const key='native-head-paint-'+index;
  return `<clipPath id="${key}-rear" clipPathUnits="userSpaceOnUse">${paint.rear.map(p=>rect(p.region)).join('')}</clipPath><mask id="${key}-front" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" x="${crop.x}" y="${crop.y}" width="${crop.width}" height="${crop.height}" style="mask-type:luminance">${rect(crop,'white')}${paint.rear.map(p=>rect(p.frontCut,'black')).join('')}</mask>`;
}
export const nativeHeadPaintDescription={version:'native-head-paint-1',method:'explicit same-source rear partitions before all body paint; original face/neck in front, both on the identical uniform head transform and discrete original cell clock; bounded authored source-pixel overlap',
  secondaryMotion:false,neckTrim:false,approved:false,productionReady:false,motionVerified:false};

import type {HostProfile} from '../host/schemas.js';
import type {PerformancePlan} from './schemas.js';
import type {ViewActingClock} from './view-acting-clock.js';
import {NativeHeadBankSchema,nativeHeadSources,nativeHeadSourceForCell,nativeHeadPixelScale,type NativeHeadBank} from './native-head-bank.js';
import {NativeHeadTrackSchema,nativeHeadCellAt,validateNativeHeadSource} from './native-head-track.js';
import {nativeHeadFaceSvg,nativeHeadFaceState,nativeHeadFaceMatrixError,type NativeFaceState,type NativeFaceEmotion} from './native-head-face.js';
import {nativeHeadIdentityMatches,isNativeHeadFaceVersion} from './native-head-identity.js';
import {nativeHeadPaintDefs} from './native-head-paint.js';

export function hasNativeHeadBank(profile:Pick<HostProfile,'appearance'>){return profile.appearance.bodyHeadBank!==undefined;}
export function hasNativeHeadSpeech(profile:Pick<HostProfile,'appearance'>){return hasNativeHeadBank(profile)&&registeredNativeHeadBank(profile).capabilities.speech;}
export function hasNativeHeadEyes(profile:Pick<HostProfile,'appearance'>){return hasNativeHeadBank(profile)&&registeredNativeHeadBank(profile).capabilities.directionalEyes;}
export function hasNativeHeadRear(profile:Pick<HostProfile,'appearance'>){return hasNativeHeadBank(profile)&&registeredNativeHeadBank(profile).cells.some(c=>c.paint?.rear.length);}
export function registeredNativeHeadBank(profile:Pick<HostProfile,'appearance'>):NativeHeadBank{
  const a=profile.appearance,b=NativeHeadBankSchema.parse(a.bodyHeadBank);
  if(a.artworkVersion!=='forest-body-view-1'||!nativeHeadIdentityMatches(a,b.actor)||!a.bodyView||!b.bodyViews.some(v=>v.view===a.bodyView))throw new Error('needs-head-turn-registration: head bank has another actor or incompatible body source');
  if(a.bodySpeech||a.bodyEyes||a.bodyExpressions||a.bodySecondary)throw new Error('needs-head-turn-registration: fixed-view face/hair overlays cannot be used on different head cells');
  return b;
}
export function validateNativeHeadBankTrack(plan:PerformancePlan,profile:Pick<HostProfile,'appearance'>){
  if(!hasNativeHeadBank(profile)&&!plan.sourceHead)return;
  if(!hasNativeHeadBank(profile)||!plan.sourceHead)throw new Error('needs-head-turn-registration: head bank and complete source track must be selected together');
  const bank=registeredNativeHeadBank(profile),track=NativeHeadTrackSchema.parse(plan.sourceHead),known=new Set(bank.cells.map(c=>c.id));
  if(track.ownerId!==plan.leadCharacterId||track.bankFingerprint!==bank.fingerprint||plan.headTurns?.length)throw new Error('needs-head-source-phase: head source actor/bank differs or local turn conflicts');
  const permitted=new Set(bank.routes.flatMap(route=>route.slice(1).map((id,i)=>route[i]+'\0'+id)));
  for(const [i,sample] of track.samples.entries()){
    if(!known.has(sample.cell))throw new Error('needs-head-turn-registration: head route requests an unregistered cell');
    if(i&&!permitted.has(track.samples[i-1]!.cell+'\0'+sample.cell))throw new Error('needs-head-turn-registration: head route skips an authored transition');
  }
  if(plan.gazes.length&&!bank.capabilities.directionalEyes)throw new Error('needs-head-turn-eyes: cell-specific directional eyes/occlusion are not registered');
  if(!bank.capabilities.expressions&&plan.expressions.some(e=>e.mood!=='neutral'&&!bank.cells.every(c=>c.restMood===e.mood)))throw new Error('needs-head-turn-expression: cell-specific emotional artwork is not registered');
}
export function nativeHeadBankCell(plan:PerformancePlan,profile:Pick<HostProfile,'appearance'>,timeMs:number,clock?:ViewActingClock){
  if(!Number.isFinite(timeMs)||timeMs<0||timeMs>plan.durationMs)throw new Error('needs-head-source-phase: head seek is outside the local shot');
  return nativeHeadBankCellAtGlobal(plan,profile,timeMs+(clock?.startMs??0),clock);
}
/** Original-history references (for a source-owned chin gesture) may precede
 * a camera slice, but can never leave the explicitly owned complete source. */
export function nativeHeadBankCellAtGlobal(plan:PerformancePlan,profile:Pick<HostProfile,'appearance'>,globalMs:number,clock?:ViewActingClock){
  const bank=registeredNativeHeadBank(profile);validateNativeHeadBankTrack(plan,profile);
  if(!clock?.headMotion)throw new Error('needs-head-source-phase: head cells require their complete storyboard source context');
  if(clock.ownerId!==plan.leadCharacterId)throw new Error('needs-head-source-phase: head clock owner differs');
  validateNativeHeadSource(plan,clock.headMotion,clock.startMs,clock.endMs,clock.runStartMs,clock.runEndMs);
  // A discrete artwork switch also switches its measured chin. Until smooth
  // correspondence/contact tracks exist, do not ask continuous arm refinement
  // to hide that finite discontinuity by stretching or teleporting the hand.
  for(const g of plan.gestures.filter(g=>g.action==='think')){
    const start=g.sourceSpan?.startMs??g.startMs+clock.startMs,end=g.sourceSpan?.endMs??g.endMs+clock.startMs;
    if(clock.headMotion.samples.slice(1).some(s=>{const at=s.atMs+clock.headMotion!.startMs;return at>start&&at<end;}))throw new Error('needs-head-turn-interaction: a head cell change during chin contact needs a registered continuous contact track');
  }
  const track=clock.headMotion,sample=nativeHeadCellAt(track,track.startMs,globalMs-track.startMs,track.endMs-track.startMs),cell=bank.cells.find(c=>c.id===sample.cell);
  if(!cell)throw new Error('needs-head-turn-registration: source cell is missing');
  return {bank,cell,sample};
}
export function nativeHeadCellAngle(cell:NativeHeadBank['cells'][number]){return -90-Math.atan2(cell.neckTop.y-cell.neck.y,cell.neckTop.x-cell.neck.x)*180/Math.PI;}
export function nativeHeadCellPoint(bank:NativeHeadBank,cell:NativeHeadBank['cells'][number],point:{x:number;y:number}){
  const a=nativeHeadCellAngle(cell)*Math.PI/180,scale=nativeHeadPixelScale(bank,cell),x=(point.x-cell.neck.x)*scale,y=(point.y-cell.neck.y)*scale;
  return {x:x*Math.cos(a)-y*Math.sin(a),y:x*Math.sin(a)+y*Math.cos(a)};
}
export function nativeHeadBankBounds(bank:NativeHeadBank){
  const points=bank.cells.flatMap(cell=>[cell.crop.x,cell.crop.x+cell.crop.width].flatMap(x=>[cell.crop.y,cell.crop.y+cell.crop.height].map(y=>nativeHeadCellPoint(bank,cell,{x,y}))));
  return {left:Math.min(...points.map(p=>p.x)),right:Math.max(...points.map(p=>p.x)),top:Math.min(...points.map(p=>p.y)),bottom:Math.max(...points.map(p=>p.y))};
}
export function nativeHeadBankFace(bank:NativeHeadBank,cellId:string){
  if(!bank.cells.some(c=>c.id===cellId))throw new Error('needs-head-turn-registration: selected face cell is missing');
  return Object.fromEntries(bank.cells.flatMap((cell,i)=>[['head-view-bank-'+i,{opacity:cell.id===cellId?1:0}],...(cell.paint?.rear.length?[['head-back-view-bank-'+i,{opacity:cell.id===cellId?1:0}]]:[])]));
}
/** Every cell retains stable path/selector keys across discrete view changes. */
export function nativeHeadBankFacialState(bank:NativeHeadBank,input:{aperture:number;blink:number;look:{x:number;y:number};emotion?:NativeFaceEmotion}):NativeFaceState{
  if(!isNativeHeadFaceVersion(bank.version)||!bank.capabilities.speech||!bank.capabilities.directionalEyes||bank.cells.some(c=>!c.face))throw new Error('needs-head-face-registration: complete source-face bank3/4/5 capabilities required');
  if(input.emotion&&!bank.capabilities.expressions)throw new Error('needs-head-turn-expression: explicit bank5 emotions required');
  const face:NativeFaceState['face']={},paths:Record<string,string>={};
  for(const [i,cell] of bank.cells.entries())if(cell.face){const a=-nativeHeadCellAngle(cell)*Math.PI/180,look={x:input.look.x*Math.cos(a)-input.look.y*Math.sin(a),y:input.look.x*Math.sin(a)+input.look.y*Math.cos(a)};
    const state=nativeHeadFaceState(cell.face,{...input,look},'native-face-'+i);Object.assign(face,state.face);Object.assign(paths,state.paths);
  }return {face,paths};
}
export function nativeHeadBankFacialError(bank:NativeHeadBank,from:NativeFaceState['face'],to:NativeFaceState['face'],wanted:NativeFaceState['face'],progress:number){
  let error=0;for(const [i,cell] of bank.cells.entries())if(cell.face)error=Math.max(error,nativeHeadFaceMatrixError(cell.face,'native-face-'+i,from,to,wanted,progress)*nativeHeadPixelScale(bank,cell));return error;
}
/** Every exact source asset is drawn once, then referenced by its cell crop and
 * uniform attachment. No anatomical labels or coordinates are mirrored. */
export function nativeHeadBankSvg(profile:HostProfile,imageUrl:(file:string,sha:string)=>string){
  const bank=registeredNativeHeadBank(profile),sources=nativeHeadSources(bank),sourceIndex=new Map(sources.map((s,i)=>[s.id,i]));
  const images=sources.map((s,i)=>{
    const url=imageUrl(s.file,s.sha256);
    if(url!=='assets/rigs/'+s.sha256+'.png'&&!/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(url))throw new Error('Unapproved native head bank image URL');
    return `<image id="native-head-bank-source-${i}" width="${s.width}" height="${s.height}" href="${url}"/>`;
  }).join('');
  return `<g data-head-bank="${bank.fingerprint}" stroke="none"><defs>${images}${bank.cells.map((c,i)=>`<clipPath id="native-head-bank-clip-${i}" clipPathUnits="userSpaceOnUse"><rect x="${c.crop.x}" y="${c.crop.y}" width="${c.crop.width}" height="${c.crop.height}"/></clipPath>${c.paint?nativeHeadPaintDefs(c.paint,c.crop,i):''}`).join('')}</defs>${bank.cells.map((c,i)=>{
    const imageId='native-head-bank-source-'+sourceIndex.get(nativeHeadSourceForCell(bank,c).id)!,rest=c.face?.mouth.rest,restId=rest?'native-head-bank-source-'+sourceIndex.get(rest.sourceId)!:undefined,
      emotionId=c.face?.emotions?'native-head-bank-source-'+sourceIndex.get(c.face.emotions.mouth.repair.sourceId)!:undefined;
    return `<g id="head-view-bank-${i}" opacity="0"><g transform="scale(${nativeHeadPixelScale(bank,c)}) rotate(${nativeHeadCellAngle(c)}) translate(${-c.neck.x} ${-c.neck.y})" clip-path="url(#native-head-bank-clip-${i})"><use href="#${imageId}"${c.paint?.rear.length?` mask="url(#native-head-paint-${i}-front)"`:''}/>${c.face?nativeHeadFaceSvg(c.face,imageId,'native-face-'+i,restId,emotionId):''}</g></g>`;
  }).join('')}</g>`;
}
/** Paint IDs/images are defined by the foreground bank exactly once. Caller
 * places this sibling BEFORE the body, with the same head attachment. It is
 * not a second independent rig or an inferred secondary-hair animation. */
export function nativeHeadBankRearSvg(profile:HostProfile){
  const bank=registeredNativeHeadBank(profile),sources=nativeHeadSources(bank),sourceIndex=new Map(sources.map((s,i)=>[s.id,i]));
  return bank.cells.flatMap((c,i)=>c.paint?.rear.length?[`<g id="head-back-view-bank-${i}" opacity="0" stroke="none"><g transform="scale(${nativeHeadPixelScale(bank,c)}) rotate(${nativeHeadCellAngle(c)}) translate(${-c.neck.x} ${-c.neck.y})" clip-path="url(#native-head-bank-clip-${i})"><g clip-path="url(#native-head-paint-${i}-rear)"><use href="#native-head-bank-source-${sourceIndex.get(nativeHeadSourceForCell(bank,c).id)!}"/></g></g></g>`]:[]).join('');
}

import type { HostProfile } from '../host/schemas.js';
import { faceLayers } from './face.js';
import { artworkSvg } from '../director/art-direction.js';
import {forestTribeArt} from './forest-tribe-art.js';
import {forestHeadSvg,usesReferenceHead} from './forest-head-art.js';
import {forestBodyArt,usesReferenceBody,referenceBodyMetrics} from './forest-body-art.js';
import {usesBodyView,registeredBodyView} from './body-view-art.js';
import {hasNativeHeadRear,nativeHeadBankRearSvg} from './body-head-bank.js';

type Point={x:number;y:number};
export interface RigMetrics {
  height:number;pelvisY:number;upperLeg:number;lowerLeg:number;hipOffset:number;stance:number;
  shoulderY:number;shoulderOffset:number;upperArm:number;lowerArm:number;headY:number;headRadius:number;
  torsoTop?:number;neckX?:number;headArtworkScale?:number;strokeWidth?:number;
  shoulders?:Record<'left'|'right',Point>;arms?:Record<'left'|'right',{upper:number;lower:number}>;
  hips?:Record<'left'|'right',Point>;legs?:Record<'left'|'right',{upper:number;lower:number}>;
  handRestRotation?:Record<'left'|'right',number>;
  /** Palm/grip origin to wrist in artwork units; length already includes bodyScale. */
  handAttachment?:Record<'left'|'right',{length:number;angleDeg:number;wristOffset:Point}>;
  /** Sole-to-ankle offset in foot artwork units, before its bodyScale. */
  footSoleOffset?:Record<'left'|'right',number>;
  armRest?:Record<'left'|'right',Point>;footOffsets?:Record<'left'|'right',number>;
  /** Positive X is the distance behind the facing direction; Y is below belt. */
  seatContactOffset?:Point;
}
export function rigMetrics(profile: HostProfile):RigMetrics {
  if(usesReferenceBody(profile))return referenceBodyMetrics(profile);
  const robot = profile.kind === 'mini-robot', b = profile.appearance.bodyScale;
  return { height: (robot ? 300 : 318) * b, pelvisY: (robot ? -78 : -128) * b,
    upperLeg: (robot ? 40 : 65) * b, lowerLeg: (robot ? 44 : 70) * b,
    hipOffset: (robot ? 15 : 7) * b, stance: (robot ? 19 : 18) * b,
    shoulderY: (robot ? -160 : -206) * b, shoulderOffset: (robot ? 44 : 25) * b,
    upperArm: 55 * b, lowerArm: 50 * b, headY: (robot ? -240 : -270) * b,
    headRadius: (robot ? 50 : 40) * profile.appearance.headScale,
  };
}

/** Logical parent transforms are baked by the compiler into independent world-space bones. */
export function performanceSvg(profile: HostProfile,imageMode:'embedded'|'scene'='embedded',heldTools=''): string {
  const m = rigMetrics(profile), a = profile.appearance, robot = profile.kind === 'mini-robot';
  const costume=(joint:string)=>(profile.costume??[]).filter(layer=>layer.joint===joint).map((layer,i)=>`<g data-costume-joint="${joint}" stroke="none" fill="#000000">${artworkSvg(layer.svg,`costume.${profile.id}.${joint}.${i}`)}</g>`).join('');
  const drawn=!!a.characterVariant,body=usesReferenceBody(profile)?forestBodyArt(profile,imageMode):null,art=drawn&&!body?forestTribeArt(profile):null;
  const view=usesBodyView(profile)?registeredBodyView(profile):undefined;
  const bone = (id: string, length: number) => `<g id="${id}"${drawn?' opacity="0"':''}><path d="M0 0V${length}"/></g>`;
  const limbs = (['left', 'right'] as const).map(side => bone(`leg-${side}-upper`, m.legs?.[side].upper??m.upperLeg)
    + bone(`leg-${side}-lower`, m.legs?.[side].lower??m.lowerLeg) + `<g id="foot-${side}">${body?.feet[side]??`<path d="M-9 0H9" stroke-width="${robot ? 12 : 6}"/>`}</g>`
    + bone(`arm-${side}-upper`, m.arms?.[side].upper??m.upperArm) + bone(`arm-${side}-lower`, m.arms?.[side].lower??m.lowerArm)
    + (body?`<defs><g id="hand-${side}">${body.hands[side]}${costume(`hand-${side}`)}</g></defs>`+(view?'':`<g id="hand-${side}-back-slot"><use href="#hand-${side}"/></g>`):
      `<g id="hand-${side}"><circle r="${robot ? 9 : drawn?3.2:5}" fill="${drawn?a.outline:a.shell}"/>${costume(`hand-${side}`)}</g>`)).join('');
  const torso = body?.torso??art?.torso??(robot ? `<rect x="-43" y="-94" width="86" height="94" rx="22" fill="${a.shell}"/><g id="badge"><circle cx="0" cy="-49" r="11" fill="${a.badge}"/></g>`
    : `<path d="M0 0V-92"/>${profile.role==='story-actor'?'':`<g id="neck-scarf"><path d="M-10 -92H10L20 -69L6 -73L0 -88Z" stroke-width="3" fill="${a.accent}"/></g>`}`);
  const head = usesReferenceHead(profile)?forestHeadSvg(profile,imageMode):art?.head??(robot ? `<g id="antenna"><path d="M0 -42V-59"/><circle cy="-63" r="5" fill="${a.accent}"/></g><rect x="-50" y="-42" width="100" height="84" rx="23" fill="${a.shell}"/><rect x="-40" y="-28" width="80" height="55" rx="12" fill="${a.screen}" stroke="none"/>`
    : `<circle r="40" fill="${a.shell}"/>`);
  const ink=(part:'leg'|'arm')=>(['left','right'] as const).map(side=>`<path id="ink-${part}-${side}" d="M0 0C0 0 0 0 0 0C0 0 0 0 0 0"/>`).join('');
  // One animated ink path per arm, referenced in exactly one painter slot.
  // Keep chin-contact stroke and mitten together above the head cutout.
  const bodyArmInk=body?`<defs>${ink('arm')}</defs>`+(view?'':(['left','right'] as const).map(side=>`<g id="ink-arm-${side}-back-slot"><use href="#ink-arm-${side}"/></g>`).join('')):'';
  const viewArmSlot=(side:'left'|'right')=>`<g data-view-depth="${side===view?.nearHand?'near':'far'}"><g id="ink-arm-${side}-back-slot"><use href="#ink-arm-${side}"/></g><g id="hand-${side}-back-slot"><use href="#hand-${side}"/></g></g>`;
  const inkPaths=drawn?(body?ink('leg'):(['left','right'] as const).map(side=>`<path id="ink-leg-${side}" d="M0 0C0 0 0 0 0 0C0 0 0 0 0 0"/><path id="ink-arm-${side}" d="M0 0C0 0 0 0 0 0C0 0 0 0 0 0"/>`).join('')):'';
  const neck=`<g id="neck"${body?' opacity="0"':''}><path d="M0 0V1" vector-effect="non-scaling-stroke"/></g>`;
  return `<g id="performer" data-profile-hash="${profile.profileHash}" fill="none" stroke="${a.outline}" stroke-width="${a.strokeWidth}" stroke-linecap="round" stroke-linejoin="round">`
    + `${body?.defs??''}${hasNativeHeadRear(profile)?`<g id="head-back">${nativeHeadBankRearSvg(profile)}</g>`:''}${inkPaths}${view?bodyArmInk+viewArmSlot(view.farHand):''}<g id="pelvis"><ellipse rx="8" ry="3" stroke="none"/>${costume('pelvis')}</g>`
    + (body?`<g id="garment-left"><g id="garment-standing-left">${body.garments.left}</g></g><g id="garment-right"><g id="garment-standing-right">${body.garments.right}</g></g>`:'')
    + `${body?.seatedGarments??''}${body?`<g id="neck-art">${body.neck}</g>${neck}`:''}<g id="chest">${torso}${costume('chest')}</g>${body?'':neck}${heldTools}${view?'':bodyArmInk}${limbs}${view?viewArmSlot(view.nearHand):''}`
    + `<g id="head">${head}${costume('head')}${drawn?'':`<g id="face-orientation">${faceLayers(0, -4, 18, robot ? a.accent : a.outline, robot ? a.screen : a.shell, 15)}</g>`}</g>`
    + (body?(['left','right'] as const).map(side=>`<g id="ink-arm-${side}-front-slot" opacity="0"><use href="#ink-arm-${side}"/></g><g id="hand-${side}-front-slot" opacity="0"><use href="#hand-${side}"/></g>`).join(''):'')+'</g>';
}

